  keys.forEach(function (k) { mx = Math.max(mx, o[k]); });
  keys.forEach(function (k) { byId('rv-o-' + k).textContent = usd(o[k]); byId('rv-b-' + k).style.width = (mx > 0 ? o[k] / mx * 100 : 0) + '%'; });
  byId('rv-o-total').textContent = usd(o.total); byId('rv-o-profit').textContent = usd(o.profit);
  var lo = CONFIG.annualProfitTargetLow, hi = CONFIG.annualProfitTargetHigh, band = byId('rv-band'), inb = o.profit >= lo ? hi >= o.profit : false;
