  var w = byId('vm-warn'); w.textContent = warn.join(' '); w.hidden = !warn.length;
  var M = [{ n: J('m_rev'), ev: rev * rm, f: J('mf_rev', { r: usds(rev), m: xx(rm) }) }, { n: J('m_ebitda'), ev: eb > 0 ? eb * em : null, f: J('mf_ebitda', { e: usds(eb), m: xx(em) }) },
    { n: J('m_dcf'), ev: D1 ? D1.ev : null, f: D1 ? J('mf_dcf', { p: usds(D1.pv), t: usds(D1.tvpv), r: pctt(r * 100), g: pctt(g * 100) }) : J('wDcf') }];
