function tourGo() { var T = MS.tour, t = tourDef(T.id), s = t.steps[T.i]; if (location.hash === '#' + s.r) { tourRender(); } else { location.hash = s.r; } setTimeout(tourRender, 30); }
function tourRender() {
  var bar = byId('cp-tour'); if (!bar) { return; } if (!MS.tour) { bar.hidden = true; return; }
  var T = MS.tour, t = tourDef(T.id), s = t.steps[T.i]; bar.hidden = false;
  setTxt('tour-name', tr(t.n)); setTxt('tour-step', J('stepOf', { a: String(T.i + 1), b: String(t.steps.length) })); setTxt('tour-t', tr(s.t)); setTxt('tour-d', tr(s.d));
  byId('tour-prev').disabled = T.i === 0; setTxt('tour-next', T.i === t.steps.length - 1 ? J('tourFinish') : J('tourNext'));
  byId('tour-fill').style.width = ((T.i + 1) / t.steps.length * 100) + '%';
}
function tourMove(d) { var T = MS.tour; if (!T) { return; } var t = tourDef(T.id), n = T.i + d; if (n >= t.steps.length) { tourEnd(); return; } if (0 > n) { return; } T.i = n; tourGo(); }
